using System;
using UnityEngine;
namespace Veilbound {
 public partial class VeilGame {
  string CityDescription(string id){switch(id){case "mine":return "Assign gathering capacity to ores. Deeper seams unlock as the mine grows.";case "hunters":return "Gather hides from the surrounding wilds. Choose which grades your hunters bring home.";case "weaver":return "Supply fibres and textiles. Split capacity across the materials your tailors need.";case "timber":return "Harvest timber from the nearby forest to build and improve your settlement.";case "quarry":return "Cut stone for construction and workshop upgrades.";case "blacksmith":return "Refine metal bars and forge weapons and plate. Each craft rolls its own bonuses.";case "tailor":return "Craft cloth equipment and capes from your gathered textiles.";default:return "Turn gathered hides into leather equipment. Each craft keeps its own rolled bonuses.";}}
  void CityBuildingPortrait(Rect r){int index=Array.IndexOf(CityMapBuildings,cityBuilding);if(index<0)index=Array.IndexOf(CityMapBuildings,cityBuilding=="tailor"?"weaver":"hunters");Vector2 p=CityBuildingPoints[index];Box(r,new Color(.015f,.02f,.021f));if(sanctuaryMap){GUI.DrawTextureWithTexCoords(r,sanctuaryMap,new Rect(p.x-.12f,1-p.y-.085f,.24f,.17f));}CardOutline(r,new Color(.21f,.22f,.19f));}
  void CityDetails(){Rect r=CityPanelRect;CityFrame(r);string id=cityBuilding;int level=city.BuildingLevel(id),src=CitySource(id);GUI.Label(new Rect(1098,207,456,37),CityBuildingName(id).ToUpper()+" / LEVEL "+level,CityType(25,cityIvory,true));CityBuildingPortrait(new Rect(1404,253,148,87));GUI.Label(new Rect(1098,260,290,76),CityDescription(id),CityType(14,muted));
   if(src>=0){CityButton(1098,355,146,35,"Production",()=>{cityDetailTab=0;cityResourcePage=0;},true,cityDetailTab==0);CityButton(1252,355,146,35,"Stockpile",()=>{cityDetailTab=1;cityResourcePage=0;},true,cityDetailTab==1);if(id!="mine")CityButton(1406,355,146,35,id=="hunters"?"Leatherworker":"Tailor",()=>SelectCityBuilding(id=="hunters"?"leatherworker":"tailor"));else CityButton(1406,355,146,35,"Blacksmith",()=>SelectCityBuilding("blacksmith"));CityProductionDetails(src);}
   else if(id=="timber"||id=="quarry")CityConstructionDetails(id);
   else CityWorkshopDetails(id);
   CityUpgradeFooter(id);
  }
  void AdjustCityAllocation(int source,int index,double delta){double current=city.Allocation(source)[index];if(city.Allocate(source,index,current+delta)){Save();notice="Allocation saved.";}}
  void CityAllocateAll(int source,int index){if(city.ProducerLevel(source)<Settlement.ResourceUnlocks[source][index])return;Array.Clear(city.Allocation(source),0,city.Allocation(source).Length);city.Allocate(source,index,city.Capacity(source));Save();notice="All capacity assigned to "+Settlement.ResourceNames[source][index]+".";}
  void CityProductionDetails(int source){double used=city.UsedCapacity(source),cap=city.Capacity(source);Rect summary=new Rect(1098,403,454,54);Box(summary,new Color(.06f,.068f,.064f));CardOutline(summary,new Color(.19f,.21f,.19f));GUI.Label(new Rect(1110,409,420,24),$"CAPACITY ALLOCATED    {used:0.#} / {cap:0.#}",CityType(16,cityIvory,true));GUI.Label(new Rect(1110,435,420,20),$"Total output: {city.TotalProduction(source):0.###} / city hour",CityType(12,muted));GUI.Label(new Rect(1098,469,230,21),cityDetailTab==0?"MATERIAL / ALLOCATION":"MATERIAL STOCK",CityType(10,muted));GUI.Label(new Rect(1302,469,108,21),"IN STOCK",CityType(10,muted,false,TextAnchor.UpperRight));GUI.Label(new Rect(1430,469,122,21),"PER CITY HOUR",CityType(10,muted,false,TextAnchor.UpperRight));
   int length=Settlement.ResourceNames[source].Length,pages=(length+3)/4;cityResourcePage=Mathf.Clamp(cityResourcePage,0,pages-1);
   for(int row=0;row<4;row++){int index=cityResourcePage*4+row;if(index>=length)break;float y=496+row*62;bool unlocked=city.ProducerLevel(source)>=Settlement.ResourceUnlocks[source][index];Color text=unlocked?cityIvory:muted;var icon=MaterialIcon(ResourceIconNames[source][index]);if(icon){GUI.color=unlocked?Color.white:new Color(.45f,.45f,.45f);GUI.DrawTexture(new Rect(1098,y+1,33,33),icon);GUI.color=Color.white;}GUI.Label(new Rect(1140,y+3,163,24),Settlement.ResourceNames[source][index],CityType(14,text));GUI.Label(new Rect(1306,y+3,104,24),city.ResourceAmount(source,index).ToString("0.##"),CityType(15,text,false,TextAnchor.UpperRight));GUI.Label(new Rect(1425,y+3,125,24),unlocked?"+"+city.ProductionRate(source,index).ToString("0.###"):"Locked",CityType(14,unlocked?new Color(.84f,.68f,.46f):muted,false,TextAnchor.UpperRight));
    if(cityDetailTab==0){double effort=city.Allocation(source)[index];GUI.Label(new Rect(1140,y+32,220,22),unlocked?"Capacity "+effort.ToString("0.#"):"Requires level "+Settlement.ResourceUnlocks[source][index],CityType(11,muted));CityButton(1360,y+29,27,25,"−",()=>AdjustCityAllocation(source,index,-1),unlocked&&effort>=1);GUI.Label(new Rect(1390,y+30,39,23),effort.ToString("0.#"),CityType(13,cityIvory,false,TextAnchor.MiddleCenter));CityButton(1434,y+29,27,25,"+",()=>AdjustCityAllocation(source,index,1),unlocked&&cap-used>=1-1e-9);CityButton(1470,y+29,80,25,"Assign all",()=>CityAllocateAll(source,index),unlocked&&cap>0);}
    else GUI.Label(new Rect(1140,y+33,410,22),unlocked?$"Yield: {Settlement.ResourceYields[source][index]:0.###} per capacity / city hour":"Unlock at level "+Settlement.ResourceUnlocks[source][index],CityType(11,muted));HudLine(new Vector2(1098,y+58),new Vector2(1552,y+58),new Color(.17f,.18f,.16f));
   }
   CityButton(1098,753,66,28,"Previous",()=>cityResourcePage--,cityResourcePage>0);GUI.Label(new Rect(1171,755,80,24),(cityResourcePage+1)+" / "+pages,CityType(12,muted,false,TextAnchor.MiddleCenter));CityButton(1257,753,66,28,"Next",()=>cityResourcePage++,cityResourcePage<pages-1);CityButton(1382,753,170,28,"Clear allocation",()=>{Array.Clear(city.Allocation(source),0,length);Save();},cityDetailTab==0&&used>0);
  }
  void CityConstructionDetails(string id){double rate=id=="timber"?city.WoodRate:city.StoneRate;string material=id=="timber"?"timber":"stone";var icon=MaterialIcon(material);if(icon)GUI.DrawTexture(new Rect(1120,392,66,66),icon);GUI.Label(new Rect(1207,397,322,34),rate.ToString("0.#")+" / city hour",CityType(27,cityIvory,true));GUI.Label(new Rect(1207,435,322,26),"Stock: "+(id=="timber"?city.wood:city.stone).ToString("N0"),CityType(16,muted));GUI.Label(new Rect(1100,500,450,68),"Building materials gather automatically. Upgrade this building to increase its output.",CityType(17,cityIvory));GUI.Label(new Rect(1100,604,450,76),"Your expedition's production multiplier applies while you are in the Veil. Only active play advances the settlement clock.",CityType(14,muted));}
  void CityWorkshopDetails(string id){bool smith=id=="blacksmith";int family=smith?3:id=="tailor"?1:2;string producer=id=="tailor"?"weaver":"hunters";GUI.Label(new Rect(1100,380,450,30),"WORKSHOP / LEVEL "+city.BuildingLevel(id),CityType(18,cityIvory,true));GUI.Label(new Rect(1100,421,450,68),smith?"Choose a metal to refine bars or forge a weapon. Armour and weapon crafts retain every rolled copy.":"Craft a new piece, compare its bonuses and equip it in your loadout. Existing pieces stay in your inventory.",CityType(16,muted));
   if(smith){CityButton(1100,520,450,45,"Refine bars & forge weapons",()=>OpenCityWorkshop(false));CityButton(1100,582,450,45,"Craft plate armour",()=>OpenCityWorkshop(true));GUI.Label(new Rect(1100,710,450,60),"Chest 8 bars · Helm / shoulders / legs 6\nSmaller pieces 4 · Greatsword 8 + grip hides",CityType(13,muted));}
   else {CityButton(1100,520,450,45,id=="tailor"?"Craft cloth & capes":"Craft leather armour",()=>{if(gearSlot>8)gearSlot=2;OpenCityWorkshop(true,family);});CityButton(1100,582,450,45,id=="tailor"?"Manage textile supply":"Manage hunting",()=>SelectCityBuilding(producer));GUI.Label(new Rect(1100,710,450,60),"Chest 8 materials · Helm / shoulders / legs 6\nSmaller pieces 4 · Secondary ingredients may apply",CityType(13,muted));}
   CityButton(1100,644,450,45,"View loadout & owned gear",()=>{tab=1;selection=0;});}
  void CityUpgradeFooter(string id){int n=city.BuildingLevel(id);Settlement.BuildingCost(n,out double woodCost,out double stoneCost);bool max=CityBuildingMax(id),afford=city.wood>=woodCost&&city.stone>=stoneCost;CityButton(1098,806,230,39,max?"Fully upgraded":n==0?"Build "+CityBuildingName(id):"Upgrade "+CityBuildingName(id),()=>Buy(id),!max&&afford);if(max){GUI.Label(new Rect(1340,808,213,38),"All material unlocks complete",CityType(13,muted));return;}Texture2D timberIcon=MaterialIcon("timber"),stoneIcon=MaterialIcon("stone");if(timberIcon)GUI.DrawTexture(new Rect(1340,810,25,25),timberIcon);if(stoneIcon)GUI.DrawTexture(new Rect(1449,810,25,25),stoneIcon);GUI.Label(new Rect(1370,812,76,28),woodCost.ToString("0"),CityType(16,afford?cityIvory:muted));GUI.Label(new Rect(1479,812,76,28),stoneCost.ToString("0"),CityType(16,afford?cityIvory:muted));}
 }
}

